package main

import (
	"bufio"
	"context"
	"errors"
	"fmt"
	"io"
	"log"
	"os"
	"path/filepath"
	"time"

	"github.com/libtmux/libtmux-go/tmux"
)

func main() {
	if err := start(); err != nil {
		log.Fatal(err)
	}
}

func start() (err error) {
	root := "/tmp/libtmux-go-test"
	if err := os.MkdirAll(root, 0700); err != nil {
		return err
	}
	directory, err := os.MkdirTemp(root, "home-")
	if err != nil {
		return err
	}

	server, err := tmux.NewServer(tmux.ServerOptions{
		Binary:     os.Getenv("TMUX_BIN"),
		SocketPath: filepath.Join(directory, "tmux.sock"),
		ConfigFile: "/dev/null",
	})
	if err != nil {
		return errors.Join(err, os.RemoveAll(directory))
	}

	defer func() {
		cleanup, cancel := context.WithTimeout(
			context.Background(),
			3*time.Second,
		)
		defer cancel()

		if stopErr := server.Kill(cleanup); stopErr != nil {
			err = errors.Join(err, stopErr)
			return // Keep the directory if cleanup fails.
		}
		err = errors.Join(err, os.RemoveAll(directory))
	}()

	ctx, cancel := context.WithTimeout(
		context.Background(),
		10*time.Second,
	)
	defer cancel()

	return run(ctx, server)
}

func run(ctx context.Context, server tmux.Server) (err error) {
	session, err := server.NewSession(ctx, tmux.NewSessionRequest{
		Name:       "libtmux-go-quickstart",
		WindowName: "start",
	})
	if err != nil {
		return fmt.Errorf("create session: %w", err)
	}

	window, err := session.NewWindow(ctx, tmux.NewWindowRequest{
		Name: new("work"),
	})
	if err != nil {
		return fmt.Errorf("create window: %w", err)
	}

	pane, err := window.SplitPane(ctx, tmux.SplitPaneRequest{
		Direction: tmux.PaneDirectionRight,
		Command:   "sh",
	})
	if err != nil {
		return fmt.Errorf("split window: %w", err)
	}

	output, err := pane.OpenObservation(ctx)
	if err != nil {
		return fmt.Errorf("watch pane: %w", err)
	}
	defer func() {
		err = errors.Join(err, output.Close())
	}()

	_, err = fmt.Fprintln(
		pane.Writer(ctx),
		"printf 'libtmux ready\\n'",
	)
	if err != nil {
		return fmt.Errorf("send command: %w", err)
	}
	scanner := bufio.NewScanner(output.Reader(ctx))
	for scanner.Scan() {
		if scanner.Text() == "libtmux ready" {
			fmt.Println("libtmux ready")
			return nil
		}
	}

	if err := scanner.Err(); err != nil {
		return fmt.Errorf("read pane: %w", err)
	}
	return io.ErrUnexpectedEOF
}

